const root = await figma.getNodeByIdAsync('5083:70358');
const all = [root, ...root.query('*').toArray()];
const ids = new Set();
for (const n of all){ const bv=n.boundVariables||{}; for(const k of Object.keys(bv)){ const v=bv[k];
  if(Array.isArray(v)){for(const a of v) if(a&&a.id) ids.add(a.id);} else if(v&&v.id) ids.add(v.id); } }
const out=[];
for (const id of ids){
  try{ const v = await figma.variables.getVariableByIdAsync(id);
    if(!v){ out.push(`${id}|MISSING`); continue; }
    const col = await figma.variables.getVariableCollectionByIdAsync(v.variableCollectionId);
    const modes = col? col.modes : [];
    const vals = modes.map(m=>{ let val=v.valuesByMode[m.modeId];
      if(val&&typeof val==='object'&&val.type==='VARIABLE_ALIAS') return `${s(m.name)}=ALIAS`;
      if(val&&typeof val==='object'&&val.r!==undefined) return `${s(m.name)}=#`+[val.r,val.g,val.b].map(x=>Math.round(x*255).toString(16).padStart(2,'0')).join('');
      return `${s(m.name)}=${typeof val==='string'?s(val):val}`; });
    out.push(`${s(v.name)}|type=${v.resolvedType}|remote=${v.remote}|coll=${col?s(col.name):'?'}|${vals.join(' ')}`);
  }catch(e){ out.push(`${id}|ERR ${s(String(e.message||e))}`); }
}
return out;

