    h: BTN_HEIGHT_LG,
    px: 'var(--zimm-scale-xl)',
    py: BTN_PADDING_Y,
    textStyle: 'button',
  },
  sm: {
    h: BTN_HEIGHT_SM,
    px: 'var(--zimm-scale-xl)',
    py: BTN_PADDING_Y,
    textStyle: 'buttonSm',
  },
};

export const Button = defineStyleConfig({
  baseStyle,
  variants,
  sizes,
